import { useState, useEffect } from 'react';
import { getRandomGreeting } from '../services/greetingService';
import { getTodayDateString, isSameDay } from '../utils/dateUtils';

const LAST_GREETING_DATE_KEY = 'lastGreetingDate';
const DAILY_GREETING_KEY = 'dailyGreeting';

export const useDailyGreeting = () => {
  const [dailyGreeting, setDailyGreeting] = useState<string>('오늘의 인사말을 불러오는 중...');

  useEffect(() => {
    const today = getTodayDateString();
    const storedLastGreetingDate = localStorage.getItem(LAST_GREETING_DATE_KEY);
    const storedDailyGreeting = localStorage.getItem(DAILY_GREETING_KEY);

    if (storedLastGreetingDate && isSameDay(storedLastGreetingDate, today) && storedDailyGreeting) {
      // If it's the same day and a greeting is stored, use it
      setDailyGreeting(storedDailyGreeting);
    } else {
      // If it's a new day or no greeting is stored, fetch a new one
      const newGreeting = getRandomGreeting();
      setDailyGreeting(newGreeting);
      localStorage.setItem(DAILY_GREETING_KEY, newGreeting);
      localStorage.setItem(LAST_GREETING_DATE_KEY, today);
    }
  }, []); // Run only once on component mount

  return dailyGreeting;
};

