/**
 * 오늘 날짜를 'YYYY-MM-DD' 형식의 문자열로 반환합니다.
 * @returns {string} 오늘 날짜 문자열
 */
export const getTodayDateString = (): string => {
  const today = new Date();
  const year = today.getFullYear();
  const month = (today.getMonth() + 1).toString().padStart(2, '0'); // 월은 0부터 시작하므로 +1
  const day = today.getDate().toString().padStart(2, '0');
  return `${year}-${month}-${day}`;
};

/**
 * 두 날짜 문자열이 같은 날짜를 나타내는지 비교합니다.
 * (예: 'YYYY-MM-DD' 형식)
 * @param {string} dateString1 첫 번째 날짜 문자열
 * @param {string} dateString2 두 번째 날짜 문자열
 * @returns {boolean} 두 날짜가 같으면 true, 아니면 false
 */
export const isSameDay = (dateString1: string, dateString2: string): boolean => {
  return dateString1 === dateString2;
};

